<template><div><div class="page-description">管理闲置资产调拨建议，接收部门确认后由管理员执行。</div><div class="tech-card"><div class="toolbar"><el-radio-group v-model="status" @change="load"><el-radio-button label="">全部</el-radio-button><el-radio-button label="pending_receiver">待确认</el-radio-button><el-radio-button label="confirmed">待执行</el-radio-button><el-radio-button label="completed">已完成</el-radio-button></el-radio-group><el-button type="primary" @click="dialog=true">新建调拨建议</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="asset_id" label="资产ID" width="100"/><el-table-column prop="source_dept_name" label="原部门"/><el-table-column prop="target_dept_name" label="接收部门"/><el-table-column prop="target_position" label="目标位置"/><el-table-column prop="target_user_name" label="使用人"/><el-table-column prop="status" label="状态" width="110"><template #default="{row}"><el-tag>{{labels[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="240"><template #default="{row}"><el-button v-if="row.status==='pending_receiver'" link type="success" @click="decide(row,true)">确认</el-button><el-button v-if="row.status==='pending_receiver'" link type="danger" @click="decide(row,false)">拒绝</el-button><el-button v-if="row.status==='confirmed'&&isAdmin" link type="primary" @click="execute(row)">执行</el-button><el-button v-if="['pending_receiver','confirmed'].includes(row.status)" link @click="cancel(row)">取消</el-button></template></el-table-column></el-table><el-pagination v-if="total" layout="total,prev,pager,next" :total="total" :page-size="20" @current-change="p=>{page=p;load()}"/></div><el-dialog v-model="dialog" title="新建调拨建议" width="520px"><el-form label-width="100px"><el-form-item label="资产ID"><el-input-number v-model="form.asset_id" :min="1"/></el-form-item><el-form-item label="接收部门"><el-select v-model="form.target_dept_id" filterable><el-option v-for="d in depts" :key="d.dept_id" :label="d.dept_name" :value="d.dept_id"/></el-select></el-form-item><el-form-item label="目标位置"><el-input v-model="form.target_position"/></el-form-item><el-form-item label="使用人"><el-input v-model="form.target_user_name"/></el-form-item><el-form-item label="建议理由"><el-input v-model="form.reason" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">提交确认</el-button></template></el-dialog></div></template>
<script setup>
import {ref,reactive,computed,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {getTransferSuggestions,createTransferSuggestion,confirmTransfer,rejectTransfer,executeTransfer,cancelTransfer,getDepartments} from '@/api';import {useUserStore} from '@/store';
const store=useUserStore(),isAdmin=computed(()=>store.user?.is_admin==1),rows=ref([]),depts=ref([]),total=ref(0),page=ref(1),status=ref(''),loading=ref(false),saving=ref(false),dialog=ref(false),labels={pending_receiver:'待确认',confirmed:'待执行',completed:'已完成',rejected:'已拒绝',cancelled:'已取消',draft:'草稿'},form=reactive({asset_id:null,target_dept_id:null,target_position:'',target_user_name:'',reason:''});
const load=async()=>{loading.value=true;try{const r=await getTransferSuggestions({status:status.value||undefined,page:page.value,size:20});rows.value=r.list;total.value=r.total}finally{loading.value=false}};const create=async()=>{saving.value=true;try{await createTransferSuggestion(form);ElMessage.success('调拨建议已提交');dialog.value=false;load()}finally{saving.value=false}};const decide=async(r,a)=>{try{await ElMessageBox.confirm(a?'确认接收该资产？':'确认拒绝该建议？');a?await confirmTransfer(r.id):await rejectTransfer(r.id);load()}catch{}};const execute=async r=>{try{await ElMessageBox.confirm('执行后将更新资产归属信息，是否继续？');await executeTransfer(r.id);ElMessage.success('调拨已执行');load()}catch{}};const cancel=async r=>{try{await cancelTransfer(r.id);load()}catch{}};onMounted(async()=>{depts.value=await getDepartments();load()});
</script><style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.page-description{margin-bottom:18px;color:#718198}.el-pagination{justify-content:flex-end;margin-top:16px}</style>
